def skill():
    n = Symbol('n', integer=True, positive=True)
    an = 1/(2*n*(n + 1))
    tot = 0
    for i in range(1, 21):
        tot += an.subs(n, i)
    v = nsimplify(tot)
    return v.p + v.q

def standard():
    # 조건에서 a_n을 직접 풀어 확인: F(n)-F(n-1)
    F = lambda n: n**2 + n
    a = {}
    for n in range(1, 21):
        c = F(n) - (F(n - 1) if n >= 2 else 0)
        a[n] = Rational(1, 1)/((n + 1)*c)
    for n in range(1, 21):
        assert sum(Rational(1, 1)/((k + 1)*a[k]) for k in range(1, n + 1)) == F(n)
    v = sum(a.values())
    return v.p + v.q

def unique():
    return [standard()]
